module AdminHelper
  def ts(component, element)
    AdminTheme.ts(component, element)
  end

  def admin_nav_link(label, path, icon: nil, coming_soon: false)
    if coming_soon
      content_tag(:span, class: ts(:nav_link, :coming_soon)) do
        safe_join([
          (heroicon(icon, classes: "w-4 h-4 flex-shrink-0") if icon),
          content_tag(:span, label),
          content_tag(:span, " -- soon", class: ts(:nav_link, :badge))
        ].compact)
      end
    else
      active = current_page?(path)
      link_to path, class: active ? ts(:nav_link, :active) : ts(:nav_link, :inactive) do
        safe_join([
          (heroicon(icon, classes: "w-4 h-4 flex-shrink-0") if icon),
          content_tag(:span, label)
        ].compact)
      end
    end
  end

  def greeting_time
    hour = Time.current.hour
    if hour < 12
      "Good morning"
    elsif hour < 17
      "Good afternoon"
    else
      "Good evening"
    end
  end

