  def heroicon(name, classes: "w-5 h-5")
    path_data = HEROICONS[name.to_sym]
    return "" unless path_data

    %(<svg class="#{classes}" fill="none" stroke="currentColor" stroke-width="1.5" viewBox="0 0 24 24">#{path_data}</svg>).html_safe
  end
